CREATE POLICY "Android release downloads" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'android-releases');
CREATE POLICY "Admins publish Android releases" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'android-releases' AND public.check_admin_access() AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Android release insert guard" ON storage.objects AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK (bucket_id <> 'android-releases' OR (public.check_admin_access() AND (storage.foldername(name))[1] = auth.uid()::text));
CREATE POLICY "Admins replace Android releases" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'android-releases' AND public.check_admin_access() AND (storage.foldername(name))[1] = auth.uid()::text) WITH CHECK (bucket_id = 'android-releases' AND public.check_admin_access() AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Android release update guard" ON storage.objects AS RESTRICTIVE FOR UPDATE TO authenticated USING (bucket_id <> 'android-releases' OR (public.check_admin_access() AND (storage.foldername(name))[1] = auth.uid()::text)) WITH CHECK (bucket_id <> 'android-releases' OR (public.check_admin_access() AND (storage.foldername(name))[1] = auth.uid()::text));
CREATE POLICY "Admins remove Android releases" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'android-releases' AND public.check_admin_access());
CREATE POLICY "Android release delete guard" ON storage.objects AS RESTRICTIVE FOR DELETE TO authenticated USING (bucket_id <> 'android-releases' OR public.check_admin_access());